8	#define MODULES_WORLD_OPENDRIVE_LANE_HPP_
9	
10	#include <string>
11	#include <vector>
12	#include <map>
13	#include "modules/geometry/commons.hpp"
14	#include "modules/geometry/line.hpp"
15	#include "modules/world/opendrive/commons.hpp"
16	
17	namespace modules {
18	namespace world {
19	namespace opendrive {
20	
21	
22	class Lane {
23	 public:
24	  Lane() : lane_id_(++lane_count), lane_position_(0),
25	           link_(), line_(), road_mark_(), speed_() {}
26	  explicit Lane(const LanePosition& lane_position) : lane_id_(++lane_count),
27	   lane_position_(lane_position), link_(), line_(), road_mark_(), speed_() {}
28	
29	  ~Lane() {}
30	
31	  //! setter functions
32	  void set_id(const LaneId lane_id) { lane_id_ = lane_id; }
33	  void set_line(const geometry::Line line) { line_ = line; }
34	  void set_link(const Link link) { link_ = link; }
35	  void set_speed(float speed) { speed_ = speed; }
36	  void set_road_mark(const RoadMark rm) { road_mark_ = rm; }
37	  void set_lane_position(const LanePosition& lane_position)
38	                             { lane_position_ = lane_position; }
39	
40	  //! getter functions
41	  geometry::Line get_line() { return line_; }
42	
43	  Link get_link() const { return link_; }
44	  RoadMark get_road_mark() const { return road_mark_; }
45	  float get_speed() const { return speed_; }
46	  LaneId get_id() const { return lane_id_; }
47	  LanePosition get_lane_position() const { return lane_position_;}
48	
49	  float curvature_at(const float s, const float s_delta = 0.01) const;
50	  float curvature_dot_at(const float s) const;
51	  float lane_width_at(const float s) const;
52	  float s_from_point(const geometry::Point2d &point) const;
53	
54	
55	 private:
56	  LaneId lane_id_;
57	  LanePosition lane_position_;
58	  Link link_;
59	  geometry::Line line_;
60	
61	  RoadMark road_mark_;
62	  float speed_;
63	
64	  static LaneId lane_count;
65	};
66	
67	inline std::string print(const Lane &l) {
68	  std::stringstream ss;
69	  ss << "id: " << l.get_id();
70	  ss << print(l.get_link());
71	  ss << print(l.get_road_mark());
72	  ss << "speed: " << l.get_speed() << std::endl;
73	  return ss.str();
74	}
75	
76	using LanePtr = std::shared_ptr<Lane>;
77	using LaneSequence = std::vector<LaneId>;
78	using LaneSequences = std::vector<LaneSequence>;
79	using Lanes = std::map<LaneId, LanePtr>;
80	
81	
82	}  // namespace opendrive
83	}  // namespace world
84	}  // namespace modules
85	
86	#endif  // MODULES_WORLD_OPENDRIVE_LANE_HPP_
