20	using LaneId = uint32_t;
21	using LanePosition = int32_t;
22	using RoadId = uint32_t;
23	
24	struct LinkInfo {
25	  LinkInfo() : position_(1000000), type_("") {}
26	  LinkInfo(const LanePosition& pos, const std::string& type) : position_(pos), type_(type) {}
27	  LanePosition position_;
28	  std::string type_;
29	};
30	
31	struct Link {
32	  Link() : predecessor_(), successor_() {}
33	  Link(const LinkInfo& predecessor, const LinkInfo& successor) : predecessor_(predecessor), successor_(successor) {}
34	  LinkInfo predecessor_;
35	  LinkInfo successor_;
36	  //! getter
37	  LinkInfo get_predecessor() const { return predecessor_; }
38	  LinkInfo get_successor() const { return successor_; }
39	  void set_predecessor(const LinkInfo& info) { predecessor_ = info; }
40	  void set_successor(const LinkInfo& info) { successor_ = info; }
41	};
42	
43	inline std::string print(const Link &l) {
44	  std::stringstream ss;
45	  ss << "Link.predecessor: " << l.predecessor_.position_ << "of type" << l.predecessor_.type_ << "; ";
46	  ss << "Link.successor: " << l.successor_.position_ << "of type" << l.successor_.type_ << std::endl;
47	  return ss.str();
48	}
49	
50	struct LaneOffset {
51	  float a, b, c, d;
52	};
53	
54	inline float polynom(float x, float a, float b, float c, float d) {
55	  return a + b * x + c * x * x + d * x * x * x;
56	}
57	
58	struct LaneLink {
59	  int from_id;
60	  int to_id;
61	};
62	
63	using LaneLinks = std::vector<LaneLink>;
64	
65	struct Connection {
66	  void add_lane_link(LaneLink link) { lane_links_.push_back(link); }
67	  LaneLinks get_lane_links() const { return lane_links_; }
68	  uint32_t id_;
69	  uint32_t incoming_road_;
70	  uint32_t connecting_road_;
71	  LaneLinks lane_links_;
72	};
73	
