75	  std::string type_;
76	  std::string color_;
77	  float width_;
78	};
79	
80	inline std::string print(const RoadMark &r) {
81	  std::stringstream ss;
82	  ss << "RoadMark: type: " << r.type_ << ", id: " << r.color_ << ", width: " << r.width_ << std::endl;
83	  return ss.str();
84	}
