18	void LaneSection::add_lane(const LanePtr& lane)  {
19	    lanes_[lane->get_id()] = lane;
20	}
21	
22	// TODO (@hart): replace dummy by real ray-check
23	LanePtr LaneSection::get_nearest_lane_on_n(double x, double y, double vx, double vy) {
24	  float x_new = x + vx;
25	  float y_new = y + vy;
26	  modules::geometry::Point2d new_point(x_new, y_new);
27	  float min_dist = 100000.0;
28	  LanePtr ret_lane_ptr = lanes_.begin()->second;
29	  
30	  for ( auto const& lane : lanes_ ) {
31	    float distance = modules::geometry::distance(lane.second->get_line(), new_point);
32	    if (distance < min_dist) {
33	      min_dist = distance;
34	      ret_lane_ptr = lane.second;
35	    }
36	  }
37	  
38	  return ret_lane_ptr;
39	}
40	
41	LanePtr LaneSection::get_lane_with_offset(const models::dynamic::State& state, double angle_offset) {
42	  double x = state[models::dynamic::StateDefinition::X_POSITION];
43	  double y = state[models::dynamic::StateDefinition::Y_POSITION];
44	  double theta = state[models::dynamic::StateDefinition::THETA_POSITION];
45	  double theta_new = theta + angle_offset;
46	
47	  LanePtr lane_ptr = get_nearest_lane_on_n(x, y, cos(theta_new), sin(theta_new));
48	  return lane_ptr;
49	}
