53	void PlanView::calc_arc_position(const float s, float initial_heading, float curvature, float &dx, float &dy) {
54	  initial_heading = fmod(initial_heading, 2 * M_PI);
55	  float hdg = initial_heading - M_PI / 2;
56	
57	  float a = 2 / curvature * sin(s * curvature / 2);
58	  float alpha = (M_PI - s * curvature) / 2 - hdg;
59	
60	  dx = -1 * a * cos(alpha);
61	  dy = a * sin(alpha);
62	
63	  // tangent = initial_heading + s * initial_curvature;
64	}
