167	inline Point2d get_point_at_s(Line l, float s) {
168	  const size_t &length = l.obj_.size();
169	  if (length <= 1) {  // this is an error Line consist of 0 or 1 element
170	    return Point2d(0, 0);
171	  } else if (s <= 0.0) {  // edge case begin
172	    return l.obj_.at(0);
173	  } else if (s >= l.s_.back()) {  // edge case end
174	    return l.obj_.at(length - 1);
175	  } else {  // nominal case
176	    int segment_end_idx = get_segment_end_idx(l, s);
177	    int segment_begin_idx = segment_end_idx - 1;
178	
179	    float s_on_segment = (s - l.s_.at(segment_begin_idx)) / (l.s_.at(segment_end_idx) - l.s_.at(segment_begin_idx));
180	    float interp_pt_x = bg::get<0>(l.obj_.at(segment_begin_idx))
181	                        + s_on_segment * (bg::get<0>(l.obj_.at(segment_end_idx))
182	                        - bg::get<0>(l.obj_.at(segment_begin_idx)));
183	    float interp_pt_y = bg::get<1>(l.obj_.at(segment_begin_idx))
184	                        + s_on_segment * (bg::get<1>(l.obj_.at(segment_end_idx))
185	                        - bg::get<1>(l.obj_.at(segment_begin_idx)));
186	    return Point2d(interp_pt_x, interp_pt_y);
187	  }
188	}
