190	inline float get_tangent_angle_at_s(Line l, float s) {
191	  if (s >= l.s_.back()) {
192	    Point2d p1 = l.obj_.at(l.obj_.size()-2);
193	    Point2d p2 = l.obj_.at(l.obj_.size()-1);
194	    return atan2(bg::get<1>(p2) - bg::get<1>(p1), bg::get<0>(p2) - bg::get<0>(p1));
195	  } else if (s <= 0.0) {
196	    Point2d p1 = l.obj_.at(0);
197	    Point2d p2 = l.obj_.at(1);
198	    return atan2(bg::get<1>(p2) - bg::get<1>(p1), bg::get<0>(p2) - bg::get<0>(p1));
199	  } else {  // not start or end
200	    int end_segment_it = get_segment_end_idx(l, s);
201	    if (check_s_for_segment_intersection(l, s)) {  // check if s is at intersection, if true then calculate the intermediate angle
202	    Point2d p1 = l.obj_.at(end_segment_it-2);
203	    Point2d p2 = l.obj_.at(end_segment_it-1);
204	    Point2d p3 = l.obj_.at(end_segment_it);
205	    float sin_mean = 0.5 * (sin(atan2(bg::get<1>(p2) - bg::get<1>(p1), bg::get<0>(p2) - bg::get<0>(p1)))
206	                      + sin(atan2(bg::get<1>(p3) - bg::get<1>(p2), bg::get<0>(p3) - bg::get<0>(p2))));
207	    float cos_mean = 0.5 * (cos(atan2(bg::get<1>(p2) - bg::get<1>(p1), bg::get<0>(p2) - bg::get<0>(p1)))
208	                      + cos(atan2(bg::get<1>(p3) - bg::get<1>(p2), bg::get<0>(p3) - bg::get<0>(p2))));
209	    return atan2(sin_mean, cos_mean);
210	    } else {  // every s not start, end or intersection
211	      Point2d p1 = l.obj_.at(end_segment_it-1);
212	      Point2d p2 = l.obj_.at(end_segment_it);
213	      return atan2(bg::get<1>(p2) - bg::get<1>(p1), bg::get<0>(p2) - bg::get<0>(p1));
214	    }
215	  }
216	}
